export interface TourDay {
  day: number | string;
  title: string;
  description: string;
}

export interface Tour {
  id: string;
  name: string;
  region: string;
  category?: string;
  days: number;
  price: string;
  image: string;
  gallery: string[];
  subtitle: string;
  description: string;
  itinerary: TourDay[];
  included: string[];
  notIncluded: string[];
  difficulty?: string;
  groupSize?: string;
  startDates: string[];
  shipName?: string;
  shipImage?: string;
  extras?: string;
  badge?: string;
  paymentTerms?: string[];
  cancellationTerms?: string[];
  hotelPricing?: {
    categories: string[];
    rows: { hotel: string; prices: string[] }[];
  };
  excursionPricing?: {
    excursions: {
      name: string;
      prices: { label: string; value: string }[];
    }[];
  };
  occupancyPricing?: {
    rows: { label: string; price: string }[];
  };
  cabinPricing?: {
    note?: string;
    footnote?: string;
    defaultCabin?: string;
    cabins: { name: string; price?: string; soldOut?: boolean }[];
  };
  groupPricing?: {
    title?: string;
    defaultGroup?: string;
    groups: { label: string; rows: { label: string; price: string }[] }[];
  };
  groupHotelPricing?: {
    title?: string;
    defaultGroup?: string;
    defaultHotel?: string;
    hotels: string[];
    twinLabel?: string;
    sglLabel?: string;
    sglByHotel: Record<string, string>;
    groups: {
      label: string;
      twinByHotel?: Record<string, string>;
      rows?: { label: string; pricesByHotel: Record<string, string> }[];
    }[];
  };
  faq?: { q: string; a: string }[];
}

